// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint128 amount) public {
        vm.assume(nonOwner != address(0) && nonOwner != c.owner());
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        bool ok;
        vm.prank(nonOwner);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        uint256 balAfter = address(c).balance;
        bool invariant = (balBefore == 0) || !ok || (ok && nonOwner == c.owner());
        assertTrue(invariant);
    }
}
